onChange.script:

if currentValue.value:
	self.view.custom.modeInfo.modeColor = system.kanoa.utilities.getFieldValue('modeColor', system.kanoa.asset.getAssetModes({'assetId': self.view.custom.modeInfo.assetId, 'modeCode': self.props.value}))
else:
	self.view.custom.modeInfo.modeColor = None

return

transforms.code:

for item in self.view.custom.modes:
	if item['value'] == value: return item['label'] == 'Production'
return False


gatewayOffsetMins = system.kanoa.date.getGatewayTimeZoneOffsetMins()
clientOffSetMins = int(self.session.props.device.timezone.utcOffset * 60.0)

offsetMins = clientOffSetMins - gatewayOffsetMins

start = system.date.format(system.date.addMinutes(value['startDate'], offsetMins), 'MM/dd/YY HH:mm')
end = system.date.format(system.date.addMinutes(value['endDate'], offsetMins), 'MM/dd/YY HH:mm')

return "Valid range from %s to %s"%(start, end)
